onTextChanged:
{{
  (async () => {
    const placa = String(
      inpCpPlaca.text || ""
    )
      .trim()
      .toUpperCase();

    if (placa.length < 5) {
      await storeValue(
        "cp_ui_vehiculo_estado_operativo",
        null
      );

      return;
    }

    /*
     * Limpia el vehículo anterior mientras se ejecuta
     * la nueva búsqueda.
     */
    await storeValue(
      "cp_ui_vehiculo_estado_operativo",
      null
    );

    const resultado =
      await qCpBuscarVehiculoPorPlaca.run();

    const placaActual = String(
      inpCpPlaca.text || ""
    )
      .trim()
      .toUpperCase();

    if (placaActual !== placa) {
      return;
    }

    await storeValue(
      "cp_ui_vehiculo_estado_operativo",
      resultado?.[0] || null
    );
  })()
}}
